INSERT INTO `wp_comments` VALUES (1,1,'Un comentarista de WordPress','wapuu@wordpress.example','https://pe.wordpress.org/','','2026-09-07 22:33:43','2026-09-08 03:33:43','Hola, esto es un comentario.\nPara empezar a moderar, editar y borrar comentarios, por favor, visita en el escritorio la pantalla de comentarios.\nLos avatares de los comentaristas provienen de <a href=\"https://gravatar.com/\">Gravatar</a>.',0,'1','','comment',0,0);
